#!/usr/bin/python3 -I
"""One-time Owner installation of a persistent, fixed-action Tokyo capability."""
import base64
import hashlib
import json
import os
from pathlib import Path
import pwd
import stat
import subprocess
import tempfile

HOST = "iZ6wee8q9z4t03hvqumwfhZ"
HELPER = Path("/usr/local/sbin/xuanjun-pr122-portal-logfix-v1")
STATE = Path("/var/lib/xuanjun-pr122-portal-logfix-capability")
RULE = Path("/etc/sudoers.d/xuanjun-pr122-portal-logfix")
PAYLOAD_SHA256 = "0e61a4cab72a18e94ed8b97c81e035ee023dfe0969c871c50651cf75792cbcbe"
PAYLOAD_B64 = ""
SOURCE_SHA256 = "528a3b5bd13dfbb5067731b3f0ae1305b28cba888658aacc09bf64cbed8b5006"


def rule_bytes():
    commands = ["sha256:" + PAYLOAD_SHA256 + " " + str(HELPER) + " " + mode
                for mode in ("status", "apply", "rollback", "revoke")]
    return ("# Owner standing authority; fixed reviewed adapter, no expiry.\n"
            "Defaults!" + str(HELPER) + " !setenv\n"
            "githubrunner ALL=(root) NOPASSWD: " + ", ".join(commands) + "\n").encode()


def require_root_chain(path):
    for node in reversed((path,) + tuple(path.parents)):
        info = node.lstat()
        if not stat.S_ISDIR(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o022:
            raise ValueError("ROOT_DIRECTORY_IDENTITY:" + str(node))


def new_file(path, data, mode):
    fd = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    with os.fdopen(fd, "wb") as handle:
        handle.write(data)
        handle.flush()
        os.fchmod(handle.fileno(), mode)
        os.fsync(handle.fileno())


def sync_dir(path):
    fd = os.open(str(path), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def main():
    if os.geteuid() != 0 or os.uname().nodename != HOST:
        raise SystemExit("ROOT_ON_APPROVED_TOKYO_REQUIRED")
    if pwd.getpwnam("githubrunner").pw_uid != 1001:
        raise SystemExit("RUNNER_IDENTITY_MISMATCH")
    os.umask(0o077)
    for parent in (HELPER.parent, STATE.parent, RULE.parent):
        require_root_chain(parent)
    for destination in (HELPER, STATE, RULE):
        if os.path.lexists(destination):
            raise SystemExit("HOLD_ALREADY_PRESENT:" + str(destination))
    source = Path("/opt/trading-system/scripts/secure_secrets_portal_server.py")
    fd = os.open(str(source), os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as handle:
        info = os.fstat(handle.fileno())
        if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != 1000
                or stat.S_IMODE(info.st_mode) != 0o755):
            raise SystemExit("SOURCE_IDENTITY_MISMATCH")
        data = handle.read(2000001)
    if hashlib.sha256(data).hexdigest() != SOURCE_SHA256:
        raise SystemExit("HOLD_SOURCE_CHANGED")
    payload = base64.b64decode(PAYLOAD_B64, validate=True)
    if hashlib.sha256(payload).hexdigest() != PAYLOAD_SHA256:
        raise SystemExit("EMBEDDED_PAYLOAD_MISMATCH")
    policy = rule_bytes()
    env = {"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LANG": "C"}
    visudo = "/usr/sbin/visudo"
    subprocess.run([visudo, "-c"], check=True, timeout=15, env=env)
    with tempfile.TemporaryDirectory(prefix="pr122-grant-", dir="/var/tmp") as raw:
        candidate = Path(raw) / "sudoers"
        new_file(candidate, policy, 0o440)
        subprocess.run([visudo, "-cf", str(candidate)], check=True, timeout=15, env=env)
        STATE.mkdir(mode=0o700)
        STATE.chmod(0o700)
        grant = {
            "schema_version": 1,
            "owner_authorization": "Owner explicitly grants standing Domestic/Tokyo website and server migration operations on 2026-10-16; revocable; no expiry",
            "scope": "OWNER_LONG_TERM_DOMESTIC_TOKYO_MIGRATION",
            "registered_adapter": "TOKYO_PR122_EXACT_LOG_FIX_ONLY",
            "commands": ["status", "apply", "rollback", "revoke"],
            "sudoers_sha256": hashlib.sha256(policy).hexdigest(),
            "helper_sha256": PAYLOAD_SHA256,
            "patch_approval": "PR122#6204793589",
            "source_sha256": SOURCE_SHA256,
            "candidate_sha256": "d5ab592a6a23dd5ebfa8689c95aaa453e371127aab9a39bc2fe7eba0febbbdf0",
            "future_adapters": "Require implementation and review under this standing Owner authorization; not automatically enabled by this adapter",
            "release_gates": "DNS/Tokyo retirement/other business gates unchanged",
        }
        new_file(STATE / "grant.json", (json.dumps(grant, indent=2, sort_keys=True) + "\n").encode(), 0o600)
        new_file(HELPER, payload, 0o755)
        # Publish the rule last, by rename within its root-owned filesystem.
        fd, pending = tempfile.mkstemp(prefix=".pr122-grant-", dir=str(RULE.parent))
        with os.fdopen(fd, "wb") as handle:
            handle.write(policy)
            handle.flush()
            os.fchmod(handle.fileno(), 0o440)
            os.fsync(handle.fileno())
        if os.path.lexists(RULE):
            raise SystemExit("HOLD_CONCURRENT_RULE")
        os.replace(pending, RULE)
        sync_dir(RULE.parent)
        result = subprocess.run([visudo, "-c"], timeout=15, env=env)
        if result.returncode:
            # Only remove the exact newly installed permission; retain evidence.
            if RULE.read_bytes() == policy:
                new_file(STATE / "sudoers.failed", policy, 0o400)
                RULE.unlink()
                sync_dir(RULE.parent)
            raise SystemExit("HOLD_FULL_SUDOERS_CHECK")
        sync_dir(STATE)
        sync_dir(STATE.parent)
        sync_dir(HELPER.parent)
    subprocess.run(["/usr/bin/sudo", "-n", "-u", "githubrunner", "--",
                    "/usr/bin/sudo", "-n", "--", str(HELPER), "status"],
                   check=True, timeout=20, env=env)
    print("PERSISTENT_SCOPED_CHANNEL_READY PATCH_APPLIED=NO SERVICE_RESTART=NO DNS_CHANGE=NO")


if __name__ == "__main__":
    main()
